	internal static Vector3I? ResolveHoverHighlightCell(
		bool editorViewActive,
		Vector3I? hoverWorldCell,
		MapEditorHoverState? editorHoverState)
	{
		if (editorViewActive && editorHoverState is { } hoverState)
