	public void ApplyPlayerCorrectionSmoothing(Vector2 worldCellOffset, float durationSeconds)
	{
		_playerVisualCorrectionOffset = worldCellOffset * new Vector2(64f, 64f);
		_playerVisualCorrectionDuration = Math.Max(0.001f, durationSeconds);
		_playerVisualCorrectionRemaining = _playerVisualCorrectionDuration;
	}

	private void AdvancePlayerCorrectionSmoothing(float deltaSeconds)
	{
		if (_playerVisualCorrectionRemaining <= 0f) return;
		_playerVisualCorrectionRemaining = Math.Max(0f, _playerVisualCorrectionRemaining - deltaSeconds);
		var ratio = _playerVisualCorrectionDuration <= 0f
			? 0f : _playerVisualCorrectionRemaining / _playerVisualCorrectionDuration;
		_playerVisualCorrectionOffset *= ratio;
		if (_playerVisualCorrectionRemaining <= 0f)
			_playerVisualCorrectionOffset = Vector2.Zero;
	}

	private void CommitPerfFrame(double frameTimeMs)
	{
		if (!_hasFrameTimeEwma)
		{
			_frameTimeEwmaMs = frameTimeMs;
			_hasFrameTimeEwma = true;
		}
		else
		{
			const double alpha = 0.10;
			_frameTimeEwmaMs = (_frameTimeEwmaMs * (1.0 - alpha)) + (frameTimeMs * alpha);
		}
		_lastPerfSnapshot = new RenderPerfSnapshot(
			(_weatherFxController?.ActiveSpriteCount ?? 0) + _spriteCount,
			_tileDrawCommandCount,
			_frameTimeEwmaMs);
	}

	public readonly record struct RenderPerfSnapshot(
		int ActiveSpriteCount,
		int DrawCommandCount,
		double FrameTimeAvgMs)
	{
		public static RenderPerfSnapshot Empty => new(0, 0, 0d);
	}

	// ── Main Render Pass ──

	public void Render()
	{
		if (_state.World == null || _root == null) return;

		_dayNight = DayNightCycle.Compute(_state.Turn);
		BeginFrame();

		var cx = _viewCenterX;
		var cy = _viewCenterY;
		var cz = _viewCenterZ;
		var halfW = _viewW / 2;
		var halfH = _viewH / 2;
		var zMin = cz - DefaultViewDepthAbove;
		var zMax = cz + DefaultViewDepthBelow;
		var highlightCell = ResolveHoverHighlightCell(_editorViewActive, HoverWorldCell, EditorHoverState);
		_editorPerspective = _editorViewActive
			? EditorPerspectiveResolver.Resolve(
				_state,
				cx,
				cy,
				cz,
				zMin,
				zMax,
				highlightCell is { } hover ? new WorldCoord(hover.X, hover.Y, cz) : null)
			: EditorPerspectiveResult.Empty;

		_drawCommands.Clear();

		for (var wy = cy - halfH; wy <= cy + halfH; wy++)
		for (var wx = cx - halfW; wx <= cx + halfW; wx++)
		for (var wz = zMax; wz >= zMin; wz--)
		{
			if (ShouldHideEditorPreviewTerrain(_editorViewActive ? EditorHoverState : null, wx, wy, wz))
				continue;

			var terrain = _state.World.GetTerrain(wx, wy, wz);
			if (terrain.StringId == Terrains.Air || terrain.StringId == Terrains.Void)
				continue;
			if (IsFullyOccluded(wx, wy, wz))
				continue;

			var topOccluded = _state.World.GetTerrain(wx, wy, wz - 1).IsOpaque;
			var drawTop = !topOccluded;
			var drawLeft = !_state.World.GetTerrain(wx, wy + 1, wz).IsOpaque;
			var drawRight = !_state.World.GetTerrain(wx + 1, wy, wz).IsOpaque;

			// 当侧面可见但顶面被遮挡时，强制绘制暗化顶面，避免"悬浮平行四边形"
			var shadowTop = false;
			if (topOccluded && (drawLeft || drawRight))
			{
				drawTop = true;
				shadowTop = true;
			}

			if (!drawTop && !drawLeft && !drawRight)
				continue;

			_drawCommands.Add(new VoxelDrawCommand
			{
				WorldX = wx, WorldY = wy, WorldZ = wz,
				ScreenPos = IsoCoordUtil.WorldToScreen(wx, wy, wz),
				SortKey = IsoCoordUtil.SortKey(wx, wy, wz),
				Terrain = terrain,
				DrawTop = drawTop, DrawLeftSide = drawLeft, DrawRightSide = drawRight,
				ShadowTop = shadowTop,
			});
		}

		_drawCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
		_lightMap.Rebuild(_state.World, cx, cy, cz, halfW, halfH, zMin, zMax);
		CollectEntityCommands(cx, cy, cz, halfW, halfH, zMin, zMax);
		CollectHoverHighlights(cx, cy, cz, halfW, halfH, zMin, zMax);
		_lastDrawCommandCount = _drawCommands.Count + _entityCommands.Count + _highlightCommandCount;
		RenderScene();
		EndFrame();
		UpdateCamera(cx, cy, cz);
	}

	private bool IsFullyOccluded(int wx, int wy, int wz)
	{
		var w = _state.World!;
		return w.GetTerrain(wx, wy, wz - 1).IsOpaque
			&& w.GetTerrain(wx, wy + 1, wz).IsOpaque
			&& w.GetTerrain(wx + 1, wy, wz).IsOpaque;
	}

	// ── Drawing Methods ──

	private const float ShadowTopDarken = 0.35f;

	private void DrawBlockTop(VoxelDrawCommand cmd)
	{
		if (!_terrainAtlas.TryGetRegions(cmd.Terrain.StringId, out var regions))
			return;
		var tint = GetFaceTint(cmd.WorldX, cmd.WorldY, cmd.WorldZ, VoxelFace.Top);
		if (cmd.ShadowTop)
			tint = new Color(tint.R * ShadowTopDarken, tint.G * ShadowTopDarken, tint.B * ShadowTopDarken, tint.A);
		tint = ApplyEditorPerspectiveAlpha(tint, cmd.WorldX, cmd.WorldY, cmd.WorldZ);
		_faceCommands.Add(new FaceSpriteCommand(
			regions.Top,
			cmd.ScreenPos,
			tint,
			cmd.SortKey));
	}

	private void DrawLeftSide(VoxelDrawCommand cmd)
	{
		if (!_terrainAtlas.TryGetRegions(cmd.Terrain.StringId, out var regions))
			return;
		var tint = ApplyEditorPerspectiveAlpha(
			GetFaceTint(cmd.WorldX, cmd.WorldY, cmd.WorldZ, VoxelFace.Left),
			cmd.WorldX,
			cmd.WorldY,
			cmd.WorldZ);
		_faceCommands.Add(new FaceSpriteCommand(
			regions.Left,
			ResolveLeftFacePosition(cmd.ScreenPos),
			tint,
			cmd.SortKey));
	}

	private void DrawRightSide(VoxelDrawCommand cmd)
	{
		if (!_terrainAtlas.TryGetRegions(cmd.Terrain.StringId, out var regions))
			return;
		var tint = ApplyEditorPerspectiveAlpha(
			GetFaceTint(cmd.WorldX, cmd.WorldY, cmd.WorldZ, VoxelFace.Right),
			cmd.WorldX,
			cmd.WorldY,
			cmd.WorldZ);
		_faceCommands.Add(new FaceSpriteCommand(
			regions.Right,
			ResolveRightFacePosition(cmd.ScreenPos),
			tint,
			cmd.SortKey));
	}

	private static Vector2 ResolveLeftFacePosition(Vector2 topCenter)
	{
		var x = topCenter.X - IsoCoordUtil.TileHalfW / 2f;
		var y = topCenter.Y + IsoCoordUtil.TileHalfH + (SideTextureHeight - 64) / 2f;
		return new Vector2(x, y);
	}

	private static Vector2 ResolveRightFacePosition(Vector2 topCenter)
	{
		var x = topCenter.X + IsoCoordUtil.TileHalfW / 2f;
		var y = topCenter.Y + IsoCoordUtil.TileHalfH + (SideTextureHeight - 64) / 2f;
		return new Vector2(x, y);
	}

	private Color GetVisionTint(int wx, int wy, int wz)
	{
		var band = _fogTracker.GetVisionBand(wx, wy, wz);
		return band switch
		{
			PlayerVisionBand.Focused => Colors.White,
			PlayerVisionBand.Peripheral => new Color(0.78f, 0.78f, 0.82f, 1.0f),
			PlayerVisionBand.Memory => new Color(0.42f, 0.42f, 0.48f, 0.88f),
			_ => new Color(0f, 0f, 0f, 1f),
		};
	}

	private Color GetFaceTint(int wx, int wy, int wz, VoxelFace face)
	{
		var visionTint = GetVisionTint(wx, wy, wz);
		if (visionTint.R <= 0f && visionTint.G <= 0f && visionTint.B <= 0f)
			return visionTint;

		var faceLight = face switch
		{
			VoxelFace.Top => _lighting.TopLight,
			VoxelFace.Left => _lighting.LeftLight,
			VoxelFace.Right => _lighting.RightLight,
			_ => 1f,
		};

		var depth = wz - _state.PlayerZ;
		var depthAttenuation = Math.Max(0.35f, 1f - depth * _lighting.DepthFalloff);
		var brightness = Math.Clamp(_lighting.Ambient * _dayNight.AmbientMultiplier * faceLight * depthAttenuation, MinLight, MaxLight);
		brightness = MathF.Pow(brightness, _lighting.Contrast);

		var ao = ComputeAmbientOcclusion(wx, wy, wz, face);
		var sunShadow = ComputeSunShadow(wx, wy, wz, face);
		var shadedBrightness = Math.Clamp(brightness * (1f - ao) * (1f - sunShadow), MinLight, MaxLight);

		// Point light contribution (additive)
		var tintR = _dayNight.SunTintR;
		var tintG = _dayNight.SunTintG;
		var tintB = _dayNight.SunTintB;

		if (_lightMap.TryGetLight(wx, wy, wz, out var cellLight))
		{
			var pointBrightness = cellLight.Intensity * 0.5f;
			shadedBrightness = Math.Clamp(shadedBrightness + pointBrightness, MinLight, MaxLight);

			// Blend point light color into tint (stronger when point light dominates)
			var blend = Math.Clamp(pointBrightness / (shadedBrightness + 0.001f) * 0.6f, 0f, 0.8f);
			tintR = tintR + (cellLight.R - tintR) * blend;
			tintG = tintG + (cellLight.G - tintG) * blend;
			tintB = tintB + (cellLight.B - tintB) * blend;
		}

		return new Color(
			Math.Clamp(visionTint.R * shadedBrightness * tintR, 0f, 1f),
			Math.Clamp(visionTint.G * shadedBrightness * tintG, 0f, 1f),
			Math.Clamp(visionTint.B * shadedBrightness * tintB, 0f, 1f),
			visionTint.A);
	}

	private float ComputeAmbientOcclusion(int wx, int wy, int wz, VoxelFace face)
	{
		if (_lighting.ShadowStrength <= 0f || _lighting.OcclusionStep <= 0f)
			return 0f;
		if (_state.World == null)
			return 0f;

		var world = _state.World;
		var ao = 0f;

		switch (face)
		{
			case VoxelFace.Top:
			{
				// 8 horizontal neighbors — direct adjacency occlusion
				const float neighborWeight = 0.06f;
				if (world.GetTerrain(wx - 1, wy, wz).IsOpaque) ao += neighborWeight;
				if (world.GetTerrain(wx + 1, wy, wz).IsOpaque) ao += neighborWeight;
				if (world.GetTerrain(wx, wy - 1, wz).IsOpaque) ao += neighborWeight;
				if (world.GetTerrain(wx, wy + 1, wz).IsOpaque) ao += neighborWeight;
				if (world.GetTerrain(wx - 1, wy - 1, wz).IsOpaque) ao += neighborWeight * 0.5f;
				if (world.GetTerrain(wx + 1, wy - 1, wz).IsOpaque) ao += neighborWeight * 0.5f;
				if (world.GetTerrain(wx - 1, wy + 1, wz).IsOpaque) ao += neighborWeight * 0.5f;
				if (world.GetTerrain(wx + 1, wy + 1, wz).IsOpaque) ao += neighborWeight * 0.5f;

				// Diagonal-above checks (blocks casting overhead shadow)
				const float aboveWeight = 0.04f;
				if (world.GetTerrain(wx + 1, wy + 1, wz - 1).IsOpaque) ao += aboveWeight;
				if (world.GetTerrain(wx - 1, wy + 1, wz - 1).IsOpaque) ao += aboveWeight;
				if (world.GetTerrain(wx + 1, wy - 1, wz - 1).IsOpaque) ao += aboveWeight;
				if (world.GetTerrain(wx - 1, wy - 1, wz - 1).IsOpaque) ao += aboveWeight;

				// Concave corner bonus: two adjacent cardinal neighbors both opaque
				const float cornerBonus = 0.08f;
				var n = world.GetTerrain(wx, wy - 1, wz).IsOpaque;
				var s = world.GetTerrain(wx, wy + 1, wz).IsOpaque;
				var w = world.GetTerrain(wx - 1, wy, wz).IsOpaque;
				var e = world.GetTerrain(wx + 1, wy, wz).IsOpaque;
				if (n && w) ao += cornerBonus;
				if (n && e) ao += cornerBonus;
				if (s && w) ao += cornerBonus;
				if (s && e) ao += cornerBonus;
				break;
			}
			case VoxelFace.Left:
			{
				// Left face is visible from -Y direction; occluded by +Y neighbors
				const float sideWeight = 0.10f;
				const float aboveSideWeight = 0.06f;
				if (world.GetTerrain(wx, wy + 1, wz).IsOpaque) ao += sideWeight;
				if (world.GetTerrain(wx, wy + 1, wz - 1).IsOpaque) ao += aboveSideWeight;
				if (world.GetTerrain(wx - 1, wy + 1, wz).IsOpaque) ao += sideWeight * 0.5f;
				// Block directly above darkens side face
				if (world.GetTerrain(wx, wy, wz - 1).IsOpaque) ao += aboveSideWeight;
				break;
			}
			case VoxelFace.Right:
			{
				// Right face is visible from -X direction; occluded by +X neighbors
				const float sideWeight = 0.10f;
				const float aboveSideWeight = 0.06f;
				if (world.GetTerrain(wx + 1, wy, wz).IsOpaque) ao += sideWeight;
				if (world.GetTerrain(wx + 1, wy, wz - 1).IsOpaque) ao += aboveSideWeight;
				if (world.GetTerrain(wx + 1, wy - 1, wz).IsOpaque) ao += sideWeight * 0.5f;
				// Block directly above darkens side face
				if (world.GetTerrain(wx, wy, wz - 1).IsOpaque) ao += aboveSideWeight;
				break;
			}
		}

		return Math.Clamp(ao * _lighting.ShadowStrength, 0f, 0.65f);
	}

	private float ComputeSunShadow(int wx, int wy, int wz, VoxelFace face)
	{
		if (_dayNight.SunAltitude <= 0.01f)
			return 0f; // no sun → no sun shadow
		if (_lighting.ShadowStrength <= 0f)
			return 0f;
		if (_state.World == null)
			return 0f;

		var world = _state.World;

		// Shadow length inversely proportional to sun altitude (longer at dawn/dusk)
		var maxSteps = (int)Math.Clamp(3f / Math.Max(0.3f, _dayNight.SunAltitude), 2, 8);

		// Sun direction: where the sun IS. Shadow is cast opposite.
		// We ray-march FROM the cell TOWARD the sun to find occluders above.
		var dirX = _dayNight.SunDirectionX;
		var dirY = _dayNight.SunDirectionY;

		var shadow = 0f;
		for (var step = 1; step <= maxSteps; step++)
		{
			var sampleX = wx + (int)MathF.Round(dirX * step);
			var sampleY = wy + (int)MathF.Round(dirY * step);
			var sampleZ = wz - step; // check cells above

			if (world.GetTerrain(sampleX, sampleY, sampleZ).IsOpaque)
			{
				// Closer occluders cast stronger shadows (inverse-distance falloff)
				var contribution = _lighting.OcclusionStep * (1f - (step - 1) / (float)(maxSteps + 1));
				shadow += contribution;
			}
		}

		var faceScale = face switch
		{
			VoxelFace.Top => 0.78f,
			VoxelFace.Left => 1.10f,
			VoxelFace.Right => 0.92f,
			_ => 1f,
		};

		return Math.Clamp(shadow * _lighting.ShadowStrength * faceScale, 0f, 0.72f);
	}

	// ── Texture Generation ──

	private CachedBlockTextures GetOrCreateTextures(TerrainDef terrain)
	{
		if (_textureCache.TryGetValue(terrain.StringId, out var cached))
			return cached;

		if (TryCreateVoxelFaceTextures(terrain, out var voxelTextures))
		{
			_textureCache[terrain.StringId] = voxelTextures;
			return voxelTextures;
		}

		// Fallback: procedural color-based diamond
		var color = TerrainColors.GetValueOrDefault(terrain.StringId, new Color(0.5f, 0.5f, 0.5f));
		var topImage = CreateDiamondImage(128, 64, color);
		var topTexture = ImageTexture.CreateFromImage(topImage);

		var leftImage = GenerateLeftSideImage(topImage);
		var rightImage = GenerateRightSideImage(topImage);

		var result = new CachedBlockTextures(
			topTexture,
			ImageTexture.CreateFromImage(leftImage),
			ImageTexture.CreateFromImage(rightImage));

		_textureCache[terrain.StringId] = result;
		return result;
	}

	private bool TryCreateVoxelFaceTextures(TerrainDef terrain, out CachedBlockTextures textures)
	{
		textures = default;
		var topPath = ResolveVoxelTopTexturePath(terrain);
		if (string.IsNullOrWhiteSpace(topPath))
			return false;

		var topSourceTexture = GetOrLoadVoxelFaceTexture(topPath);
		if (topSourceTexture == null)
			return false;

		var topSourceImage = ExtractImage(topSourceTexture);
		if (topSourceImage == null)
			return false;

		var topDiamondImage = VoxelFaceImageUtil.BuildTopDiamond(topSourceImage);
		topDiamondImage = VoxelFaceImageUtil.EnhanceTopFaceEdges(topDiamondImage, GetTopEdgeStrength(terrain));
		var topTexture = ImageTexture.CreateFromImage(topDiamondImage);

		Image sideSourceImage;
		var sidePath = ResolveVoxelSideTexturePath(terrain);
		var sideTexture = string.IsNullOrWhiteSpace(sidePath) ? null : GetOrLoadVoxelFaceTexture(sidePath);
		if (sideTexture != null)
			sideSourceImage = ExtractImage(sideTexture) ?? topSourceImage;
		else
			sideSourceImage = topSourceImage;

		var wallLike = IsWallTerrain(terrain);
		var leftDarken = wallLike ? WallLeftSideDarken : DefaultLeftSideDarken;
		var rightDarken = wallLike ? WallRightSideDarken : DefaultRightSideDarken;
		var faceHeight = wallLike ? WallSideFaceHeight : SideFaceHeight;
		var leftImage = VoxelFaceImageUtil.GenerateSideFace(sideSourceImage, isRight: false, leftDarken, faceHeight);
		var rightImage = VoxelFaceImageUtil.GenerateSideFace(sideSourceImage, isRight: true, rightDarken, faceHeight);
		VoxelFaceImageUtil.EnhanceSideFaceEdge(leftImage, isRight: false, edgeStrength: GetSideEdgeStrength(terrain));
		VoxelFaceImageUtil.EnhanceSideFaceEdge(rightImage, isRight: true, edgeStrength: GetSideEdgeStrength(terrain));

		textures = new CachedBlockTextures(
			topTexture,
			ImageTexture.CreateFromImage(leftImage),
			ImageTexture.CreateFromImage(rightImage));
		return true;
	}

	private Texture2D? GetOrLoadVoxelFaceTexture(string path)
	{
		if (_voxelFaceTextureCache.TryGetValue(path, out var cached))
			return cached;

		var loaded = GD.Load<Texture2D>(path);
		_voxelFaceTextureCache[path] = loaded;
		return loaded;
	}

