	private static string ResolveVoxelTopTexturePath(TerrainDef terrain)
	{
		var token = string.IsNullOrWhiteSpace(terrain.TopTile) ? terrain.StringId : terrain.TopTile;
		var fileName = ResolveVoxelFileName(token, isTop: true);
		return string.IsNullOrWhiteSpace(fileName) ? string.Empty : $"{VoxelTileRoot}/{fileName}";
	}

	private static string ResolveVoxelSideTexturePath(TerrainDef terrain)
	{
		var token = string.IsNullOrWhiteSpace(terrain.SideTile) ? terrain.StringId : terrain.SideTile;
		var fileName = ResolveVoxelFileName(token, isTop: false);
		return string.IsNullOrWhiteSpace(fileName) ? string.Empty : $"{VoxelTileRoot}/{fileName}";
	}

	private static string ResolveVoxelFileName(string token, bool isTop)
	{
		if (VoxelTileAliases.TryGetValue(token, out var alias))
			return alias;

		var inferred = token switch
		{
			"grass_block" => isTop ? "tile_grass_top.png" : "tile_grass_side.png",
			"grass" => isTop ? "tile_grass_top.png" : "tile_grass_side.png",
			"tree" => "tile_grass_side.png",
			"fungus" => "tile_grass_side.png",
			"dirt" => "tile_dirt.png",
			"swamp" => "tile_dirt.png",
			"marsh" => "tile_dirt.png",
			"sand" => "tile_dirt.png",
			"wall_soil" => "tile_dirt.png",
			"stone" => "tile_stone.png",
			"gravel" => "tile_stone.png",
			"mountain" => "tile_stone.png",
			"rubble" => "tile_stone.png",
			"floor" => "tile_stone.png",
			"wall_stone" => "tile_stone.png",
			"wall_granite" => "tile_stone.png",
			"wall_obsidian" => "tile_stone.png",
			"wall_iron" => "tile_stone.png",
			"crystal_vein" => "tile_stone.png",
			_ => string.Empty,
		};

		return inferred;
	}

	private static float GetTopEdgeStrength(TerrainDef terrain)
	{
		if (IsWallTerrain(terrain))
			return WallTopEdgeStrength;
		return terrain.Solid ? SolidTopEdgeStrength : NonSolidTopEdgeStrength;
	}

	private static float GetSideEdgeStrength(TerrainDef terrain)
	{
		if (IsWallTerrain(terrain))
			return WallSideEdgeStrength;
		return terrain.Solid ? SolidSideEdgeStrength : NonSolidSideEdgeStrength;
	}

	private static bool IsWallTerrain(TerrainDef terrain)
	{
		return terrain.StringId.StartsWith("wall_", StringComparison.OrdinalIgnoreCase)
			|| terrain.StringId.Equals(Terrains.Stone, StringComparison.OrdinalIgnoreCase)
			|| terrain.StringId.Equals(Terrains.Dirt, StringComparison.OrdinalIgnoreCase)
			|| terrain.StringId.Equals(Terrains.Mountain, StringComparison.OrdinalIgnoreCase);
	}

	/// <summary>
	/// Extract the top tile as an Image from an AtlasTexture or regular Texture2D.
	/// </summary>
	private static Image? ExtractImage(Texture2D texture)
	{
		if (texture is AtlasTexture atlas)
		{
			var fullImage = atlas.Atlas?.GetImage();
			if (fullImage == null) return null;
			var region = atlas.Region;
			return fullImage.GetRegion(new Rect2I(
				(int)region.Position.X, (int)region.Position.Y,
				(int)region.Size.X, (int)region.Size.Y));
		}
		return texture.GetImage();
	}

	/// <summary>
	/// Generate left side face as a 64x64 parallelogram image.
	/// The parallelogram covers the area below the diamond's bottom-left edge:
	///   TL=(0,0) TR=(63,31) BR=(63,63) BL=(0,32)  (in image coords)
	/// Colors are sampled from the left-bottom edge of the top diamond, darkened by LeftDarken.
	/// </summary>
	private static Image GenerateLeftSideImage(Image topImage)
	{
		const int iw = SideTextureWidth;
		const int ih = SideTextureHeight;
		const int faceH = SideFaceHeight;
		var img = Image.CreateEmpty(iw, ih, false, Image.Format.Rgba8);
		var tw = topImage.GetWidth();
		var th = topImage.GetHeight();
		var halfW = tw / 2;
		var halfH = th / 2;

		for (var px = 0; px < iw; px++)
		{
			var t = px / (float)(iw - 1);
			var sampleX = (int)(t * halfW);
			var sampleY = halfH + (int)(t * (halfH - 1));
			sampleX = Math.Clamp(sampleX, 0, tw - 1);
			sampleY = Math.Clamp(sampleY, 0, th - 1);
			var color = VoxelFaceImageUtil.SampleArea(topImage, sampleX, sampleY, tw, th);

			var pyStart = (int)Math.Round(px * IsoCoordUtil.TileHalfH / (double)(iw - 1));
			for (var dy = 0; dy < faceH; dy++)
			{
				var py = pyStart + dy;
				if (py >= ih) break;
				var gradientFactor = 1.0f - (dy / (float)faceH) * 0.2f;
				var c = color * new Color(LeftDarken * gradientFactor, LeftDarken * gradientFactor, LeftDarken * gradientFactor, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}
		return img;
	}

	/// <summary>
	/// Generate right side face as a 64x64 parallelogram image.
	/// The parallelogram covers the area below the diamond's bottom-right edge:
	///   TL=(0,32) TR=(63,0) BR=(63,32) BL=(0,64)  (in image coords)
	/// Colors are sampled from the right-bottom edge of the top diamond, darkened by RightDarken.
	/// </summary>
	private static Image GenerateRightSideImage(Image topImage)
	{
		const int iw = SideTextureWidth;
		const int ih = SideTextureHeight;
		const int faceH = SideFaceHeight;
		var img = Image.CreateEmpty(iw, ih, false, Image.Format.Rgba8);
		var tw = topImage.GetWidth();
		var th = topImage.GetHeight();
		var halfW = tw / 2;
		var halfH = th / 2;

		for (var px = 0; px < iw; px++)
		{
			var t = px / (float)(iw - 1);
			var sampleX = halfW + (int)(t * (halfW - 1));
			var sampleY = (th - 1) - (int)(t * (halfH - 1));
			sampleX = Math.Clamp(sampleX, 0, tw - 1);
			sampleY = Math.Clamp(sampleY, 0, th - 1);
			var color = VoxelFaceImageUtil.SampleArea(topImage, sampleX, sampleY, tw, th);

			var pyStart = (int)Math.Round((iw - 1 - px) * IsoCoordUtil.TileHalfH / (double)(iw - 1));
			for (var dy = 0; dy < faceH; dy++)
			{
				var py = pyStart + dy;
				if (py >= ih) break;
				var gradientFactor = 1.0f - (dy / (float)faceH) * 0.2f;
				var c = color * new Color(RightDarken * gradientFactor, RightDarken * gradientFactor, RightDarken * gradientFactor, 1f);
				c.A = color.A;
				img.SetPixel(px, py, c);
			}
		}
		return img;
	}

	/// <summary>Create a solid-color diamond image (fallback when no atlas tile available).</summary>
	private static Image CreateDiamondImage(int w, int h, Color color)
	{
		var image = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
		var halfW = w / 2;
		var halfH = h / 2;
		for (var py = 0; py < h; py++)
		for (var px = 0; px < w; px++)
		{
			var dx = Math.Abs(px - halfW) / (float)halfW;
			var dy = Math.Abs(py - halfH) / (float)halfH;
			image.SetPixel(px, py, dx + dy <= 1.0f ? color : Colors.Transparent);
		}
		return image;
	}

	// ── Entity Rendering ──

	private static readonly Vector2 DefaultEntitySpriteScale = new(0.25f, 0.25f);
	private static readonly Vector2 EntitySpriteBaseOffset = new(0f, -8f);
	private static readonly Vector2 DefaultFacilitySpriteScale = new(0.72f, 0.72f);
	private static readonly Vector2 FacilitySpriteBaseOffset = Vector2.Zero;
	private static readonly Vector2 DefaultWorldEntitySpriteScale = new(0.62f, 0.62f);
	private static readonly Vector2 WorldEntitySpriteBaseOffset = Vector2.Zero;
	private readonly Dictionary<string, ImageTexture> _entityMarkerCache = new();
	private readonly Dictionary<string, FacilityFrameBounds> _facilityFrameBoundsCache = new();

	private void CollectEntityCommands(int cx, int cy, int cz, int halfW, int halfH, int zMin, int zMax)
	{
		_entityCommands.Clear();

		if (!_editorViewActive)
		{
			foreach (var actor in _state.Actors.Values)
			{
				if (actor.Z < zMin || actor.Z > zMax) continue;
				if (Math.Abs(actor.X - cx) > halfW || Math.Abs(actor.Y - cy) > halfH) continue;
				if (_fogTracker.GetVisionBand(actor.X, actor.Y, actor.Z) == PlayerVisionBand.Unknown) continue;
				var tint = GetVisionTint(actor.X, actor.Y, actor.Z);
				var label = actor.Id == _state.PlayerId ? "P" : (actor.Faction == Factions.Hostile ? "!" : "?");
				_entityCommands.Add(new EntityDrawCommand(
					IsoCoordUtil.SortKey(actor.X, actor.Y, actor.Z),
					IsoCoordUtil.WorldToScreen(actor.X, actor.Y, actor.Z),
					actor,
					null,
					null,
					label,
					tint));
			}
		}

		foreach (var facility in _state.Facilities.Values)
		{
			if (!TryBuildFacilityDrawCommand(facility, cx, cy, halfW, halfH, zMin, zMax, out var command))
				continue;

			_entityCommands.Add(command);
		}

		for (var wy = cy - halfH; wy <= cy + halfH; wy++)
		for (var wx = cx - halfW; wx <= cx + halfW; wx++)
		for (var wz = zMax; wz >= zMin; wz--)
		{
			var entities = _state.World!.GetEntities(wx, wy, wz);
			if (entities.Count == 0) continue;
			if (_fogTracker.GetVisionBand(wx, wy, wz) == PlayerVisionBand.Unknown) continue;
			var tint = GetVisionTint(wx, wy, wz);
			var pos = IsoCoordUtil.WorldToScreen(wx, wy, wz);
			var key = IsoCoordUtil.SortKey(wx, wy, wz);
			foreach (var e in entities)
			{
				if (ShouldHideEditorPreviewFixture(_editorViewActive ? EditorHoverState : null, wx, wy, wz, e.EntityId))
					continue;
				_entityCommands.Add(new EntityDrawCommand(key, pos, null, null, e.EntityId, e.Glyph, tint));
			}
		}

		_entityCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
	}

	private void RenderScene()
	{
		_faceCommands.Clear();

		for (var i = 0; i < _drawCommands.Count; i++)
		{
			var terrain = _drawCommands[i];
			if (terrain.DrawTop) DrawBlockTop(terrain);
			if (terrain.DrawLeftSide) DrawLeftSide(terrain);
			if (terrain.DrawRightSide) DrawRightSide(terrain);
		}

		_faceCommands.Sort(static (a, b) => a.SortKey.CompareTo(b.SortKey));
		_faceBatchCanvas?.SetCommands(_faceCommands);

		for (var i = 0; i < _entityCommands.Count; i++)
		{
			var entity = _entityCommands[i];
			if (entity.Actor != null && TryDrawActorSprite(entity.ScreenPos, entity.Actor, entity.Tint))
				continue;
			if (entity.Facility != null && TryDrawFacilitySprite(entity.ScreenPos, entity.Facility, entity.Tint))
				continue;
			if (!string.IsNullOrWhiteSpace(entity.EntityId) && TryDrawWorldEntitySprite(entity.ScreenPos, entity.EntityId, entity.Tint))
				continue;
			DrawEntityMarker(entity.ScreenPos, entity.Label, entity.Tint);
		}

		RenderHoverHighlights();
	}

	private static HoverHighlightStyle ResolveHoverHighlightStyle(
		bool editorViewActive,
		MapEditorHoverState? editorHoverState)
	{
		if (!editorViewActive || editorHoverState is not { } hoverState)
			return DefaultHoverHighlightStyle;

		return hoverState.ToolMode switch
		{
			MapEditorToolMode.Select => EditorSelectHoverHighlightStyle,
			MapEditorToolMode.Demolish => EditorDemolishHoverHighlightStyle,
			_ => hoverState.CanApply
				? EditorBuildPlaceableHoverHighlightStyle
				: EditorBuildBlockedHoverHighlightStyle,
		};
	}

	private void CollectHoverHighlights(int cx, int cy, int cz, int halfW, int halfH, int zMin, int zMax)
	{
		_highlightCommands.Clear();
		_highlightCommandCount = 0;
		var editorHoverState = _editorViewActive ? EditorHoverState : null;
		var highlightCell = ResolveHoverHighlightCell(_editorViewActive, HoverWorldCell, editorHoverState);
		if (highlightCell is not { } hover)
			return;
		if (Math.Abs(hover.X - cx) > halfW || Math.Abs(hover.Y - cy) > halfH)
			return;
		if (hover.Z < zMin || hover.Z > zMax)
			return;
		if (_fogTracker.GetVisionBand(hover.X, hover.Y, hover.Z) == PlayerVisionBand.Unknown)
			return;

		var basePos = IsoCoordUtil.WorldToScreen(hover.X, hover.Y, hover.Z);
		_highlightCommands.Add(new HoverHighlightCommand(
			basePos,
			hover,
			ResolveHoverHighlightStyle(_editorViewActive, editorHoverState),
			IsoCoordUtil.SortKey(hover.X, hover.Y, hover.Z) + 9000,
			editorHoverState));
		_highlightCommandCount = _highlightCommands.Count + GetEditorPlacementGhostCommandCount(editorHoverState);
	}

	private void RenderHoverHighlights()
	{
		var pulse = 0.55f + 0.45f * (0.5f + 0.5f * Mathf.Sin(Time.GetTicksMsec() / 320.0f));
		for (var i = 0; i < _highlightCommands.Count; i++)
		{
			var command = _highlightCommands[i];
			if (command.EditorHoverState is { } editorHoverState && ShouldDrawEditorPlacementGhost(editorHoverState))
				DrawEditorPlacementGhost(command.ScreenPos, editorHoverState);

			var geometry = BuildHoverVolumeGeometry(command.ScreenPos);
			var fillTint = ApplyEditorPerspectiveAlpha(
				command.Style.FillTint * new Color(1f, 1f, 1f, pulse),
				command.WorldCell.X, command.WorldCell.Y, command.WorldCell.Z);
			var sideTint = ApplyEditorPerspectiveAlpha(
				command.Style.SideTint * new Color(1f, 1f, 1f, 0.75f + pulse * 0.25f),
				command.WorldCell.X, command.WorldCell.Y, command.WorldCell.Z);
			var edgeTint = ApplyEditorPerspectiveAlpha(
				command.Style.OutlineTint * new Color(1f, 1f, 1f, 0.65f + pulse * 0.35f),
				command.WorldCell.X, command.WorldCell.Y, command.WorldCell.Z);
			DrawHoverVolumeFaces(geometry.TopCenter, sideTint);
			DrawHoverVolumeEdges(geometry, edgeTint);
			DrawHoverDiamond(command.ScreenPos, edgeTint, HoverCellOutlineScale, zIndex: 3, textureKey: HoverDiamondOutlineTextureKey);
			DrawHoverDiamond(command.ScreenPos, fillTint, HoverCellFillScale, zIndex: 4, textureKey: HoverDiamondFillTextureKey);
		}
	}

	private void DrawEditorPlacementGhost(Vector2 screenPos, MapEditorHoverState hoverState)
	{
		if (string.IsNullOrWhiteSpace(hoverState.GhostRenderId))
			return;

		switch (hoverState.Kind)
		{
			case MapEditorHoverStateKind.Terrain:
				DrawTerrainPlacementGhost(screenPos, hoverState.GhostRenderId);
				break;
			case MapEditorHoverStateKind.Fixture:
				DrawFixturePlacementGhost(screenPos, hoverState.GhostRenderId, hoverState.GhostGlyph);
				break;
		}
	}

	private void DrawTerrainPlacementGhost(Vector2 screenPos, string? terrainId)
	{
		if (string.IsNullOrWhiteSpace(terrainId))
			return;

		var terrain = TerrainRegistry.Get(terrainId);
		var atlasTexture = _terrainAtlas.AtlasTexture;
		if (terrain == null || atlasTexture == null)
			return;
		if (terrain.StringId is Terrains.Air or Terrains.Void)
			return;
		if (!_terrainAtlas.TryGetRegions(terrain.StringId, out var regions))
			return;

		var tint = new Color(1f, 1f, 1f, EditorPlacementGhostAlpha);
		DrawAtlasRegionSprite(atlasTexture, regions.Left, ResolveLeftFacePosition(screenPos), tint, zIndex: 1);
		DrawAtlasRegionSprite(atlasTexture, regions.Right, ResolveRightFacePosition(screenPos), tint, zIndex: 1);
		DrawAtlasRegionSprite(atlasTexture, regions.Top, screenPos, tint, zIndex: 2);
	}

	private void DrawFixturePlacementGhost(Vector2 screenPos, string? entityId, string? glyph)
	{
		if (string.IsNullOrWhiteSpace(entityId))
			return;

		var tint = new Color(1f, 1f, 1f, EditorPlacementGhostAlpha);
		if (TryDrawWorldEntitySprite(screenPos, entityId, tint))
			return;

		DrawEntityMarker(screenPos, glyph ?? entityId, tint);
	}

	private void DrawHoverVolumeFaces(Vector2 cellPos, Color tint)
	{
		DrawHoverSideFace(ResolveLeftFacePosition(cellPos), tint, HoverSideLeftFillTextureKey, zIndex: 1);
		DrawHoverSideFace(ResolveRightFacePosition(cellPos), tint, HoverSideRightFillTextureKey, zIndex: 1);
	}

	private void DrawHoverVolumeEdges(HoverVolumeGeometry geometry, Color tint)
	{
		DrawHoverEdge(geometry.Left, geometry.LowerLeft, tint, zIndex: 2);
		DrawHoverEdge(geometry.Bottom, geometry.LowerBottom, tint, zIndex: 2);
		DrawHoverEdge(geometry.Right, geometry.LowerRight, tint, zIndex: 2);
		DrawHoverEdge(geometry.LowerLeft, geometry.LowerBottom, tint, zIndex: 2);
		DrawHoverEdge(geometry.LowerBottom, geometry.LowerRight, tint, zIndex: 2);
	}

	private void DrawHoverSideFace(Vector2 pos, Color tint, string textureKey, int zIndex)
	{
		var sprite = AcquireSprite();
		sprite.Centered = true;
		sprite.Texture = GetEntityMarkerTexture(textureKey);
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Linear;
		sprite.RegionEnabled = false;
		sprite.Skew = 0f;
		sprite.Scale = Vector2.One;
		sprite.Position = pos;
		sprite.Rotation = 0f;
		sprite.ZIndex = zIndex;
		sprite.Modulate = tint;
		sprite.Visible = true;
	}

	private void DrawHoverEdge(Vector2 from, Vector2 to, Color tint, int zIndex)
	{
		var mid = (from + to) * 0.5f;
		var dir = to - from;
		var len = dir.Length();
		if (len < 1f)
			return;

		var sprite = AcquireSprite();
		sprite.Centered = true;
		sprite.Texture = GetEntityMarkerTexture(HoverEdgeSegmentTextureKey);
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Linear;
		sprite.RegionEnabled = false;
		sprite.Skew = 0f;
		sprite.Scale = new Vector2(len / 32f, 1f);
		sprite.Position = mid;
		sprite.Rotation = dir.Angle();
		sprite.ZIndex = zIndex;
		sprite.Modulate = tint;
		sprite.Visible = true;
	}

	private void DrawHoverDiamond(Vector2 pos, Color tint, Vector2 scale, int zIndex, string textureKey)
	{
		var sprite = AcquireSprite();
		sprite.Centered = true;
		sprite.Texture = GetEntityMarkerTexture(textureKey);
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Linear;
		sprite.RegionEnabled = false;
		sprite.Scale = scale;
		sprite.Position = pos;
		sprite.Skew = 0f;
		sprite.ZIndex = zIndex;
		sprite.Modulate = tint;
		sprite.Visible = true;
	}

	private void DrawAtlasRegionSprite(Texture2D texture, Rect2 sourceRegion, Vector2 position, Color tint, int zIndex)
	{
		var sprite = AcquireSprite();
		sprite.Centered = true;
		sprite.Texture = texture;
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Nearest;
		sprite.RegionEnabled = true;
		sprite.RegionRect = sourceRegion;
		sprite.Scale = Vector2.One;
		sprite.Position = position;
		sprite.Skew = 0f;
		sprite.Rotation = 0f;
		sprite.ZIndex = zIndex;
		sprite.Modulate = tint;
		sprite.Visible = true;
	}

	private Color ApplyEditorPerspectiveAlpha(Color tint, int worldX, int worldY, int worldZ)
	{
		if (!_editorViewActive || !_editorPerspective.ShouldFade(worldX, worldY, worldZ))
			return tint;

		return new Color(tint.R, tint.G, tint.B, tint.A * EditorPerspectiveResolver.SoftFadeAlpha);
	}

	private bool TryDrawActorSprite(Vector2 pos, Actor actor, Color tint)
	{
		if (!TryResolveActorSpriteVisual(actor, out var visual))
			return false;

		var size = visual.Region?.Size ?? visual.Texture.GetSize();
		var sprite = AcquireSprite();
		sprite.Centered = false;
		sprite.Texture = visual.Texture;
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Nearest;
		sprite.RegionEnabled = visual.Region != null;
		if (visual.Region is { } region)
			sprite.RegionRect = region;
		sprite.Scale = visual.Scale;
		sprite.Skew = 0f;
		sprite.ZIndex = 1;
		sprite.Modulate = tint;
		sprite.Position = pos + EntitySpriteBaseOffset + visual.Offset + new Vector2(
			-(size.X * visual.Scale.X) / 2f,
			-(size.Y * visual.Scale.Y));
		sprite.Visible = true;
		return true;
	}

	private bool TryDrawFacilitySprite(Vector2 pos, FacilityInstance facility, Color tint)
	{
		if (!TryResolveFacilitySpriteVisual(facility, out var visual))
			return false;

		var size = visual.Region?.Size ?? visual.Texture.GetSize();
		var sprite = AcquireSprite();
		sprite.Centered = false;
		sprite.Texture = visual.Texture;
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Nearest;
		sprite.RegionEnabled = visual.Region != null;
		if (visual.Region is { } region)
			sprite.RegionRect = region;
		sprite.Scale = visual.Scale;
		sprite.Skew = 0f;
		sprite.ZIndex = 1;
		sprite.Modulate = tint * ResolveFacilityStageTint(facility.Stage);
		sprite.Position = ResolveFacilitySpritePosition(pos, size, visual);
		sprite.Visible = true;
		return true;
	}

	private bool TryResolveActorSpriteVisual(Actor actor, out ActorSpriteVisual visual)
	{
		visual = default;
		var entry = ResolveActorRenderEntry(actor);
		if (entry == null)
			return false;

		Texture2D? texture = null;
		Rect2? region = null;
		if (IsTextureEntry(entry) && entry.TexturePath is { Length: > 0 } texturePath)
		{
			texture = ResAccess.Get<Texture2D>(texturePath);
			if (texture != null)
				region = ResolveEntitySpriteRegion(entry, actor, texture);
		}
		else if (IsSpriteSheetEntry(entry))
		{
			var sheetPath = ResolveCharacterSheetPath(entry);
			if (sheetPath.Length > 0)
			{
				texture = ResAccess.Get<Texture2D>(sheetPath);
				if (texture != null)
					region = ResolveCharacterSheetRegion(entry, actor, texture);
			}
		}

		if (texture == null)
			return false;

		visual = new ActorSpriteVisual(
			texture,
			region,
			ResolveEntitySpriteScale(entry.Scale),
			ResolveEntitySpriteOffset(entry.Offset));
		return true;
	}

	private bool TryResolveFacilitySpriteVisual(FacilityInstance facility, out FacilitySpriteVisual visual)
	{
		visual = default;
		var entry = ResolveFacilityRenderEntry(facility);
		if (entry == null || entry.TexturePath is not { Length: > 0 } texturePath)
			return false;

		var texture = ResAccess.Get<Texture2D>(texturePath);
		if (texture == null)
			return false;

		var region = ResolveFacilitySpriteRegion(entry, facility, texture);
		visual = new FacilitySpriteVisual(
			texture,
			region,
			ResolveFacilitySpriteScale(entry.Scale),
			ResolveEntitySpriteOffset(entry.Offset),
			ResolveFacilityFrameBounds(texturePath, texture, region));
		return true;
	}

	private bool TryBuildFacilityDrawCommand(
		FacilityInstance facility,
		int cx,
		int cy,
		int halfW,
		int halfH,
		int zMin,
		int zMax,
		out EntityDrawCommand command)
	{
		command = default;
		if (facility.Z < zMin || facility.Z > zMax)
			return false;

		var footprint = _state.World!.GetFootprintCells(facility);
		if (footprint.Count == 0)
			return false;

		var placement = ResolveFacilityRenderPlacement(footprint, cx, cy, halfW, halfH);
		if (!placement.Visible)
			return false;

		var def = FacilityRegistry.Get(facility.FacilityDefId);
		var label = def?.Glyph is { Length: > 0 } glyph ? glyph : "#";
		command = new EntityDrawCommand(
			placement.SortKey - 1,
			placement.ScreenPos,
			null,
			facility,
			facility.FacilityDefId,
			label,
			placement.Tint);
		return true;
	}

	private FacilityRenderPlacement ResolveFacilityRenderPlacement(
		IReadOnlyList<ZoneCell> footprint,
		int cameraX,
		int cameraY,
		int halfW,
		int halfH)
	{
		var inView = false;
		var visible = false;
		var sortKey = long.MinValue;
		var tint = Colors.White;

		for (var index = 0; index < footprint.Count; index++)
		{
			var cell = footprint[index];
			sortKey = Math.Max(sortKey, IsoCoordUtil.SortKey(cell.X, cell.Y, cell.Z));

			if (Math.Abs(cell.X - cameraX) > halfW || Math.Abs(cell.Y - cameraY) > halfH)
				continue;

			inView = true;

			if (_fogTracker.GetVisionBand(cell.X, cell.Y, cell.Z) == PlayerVisionBand.Unknown)
				continue;

			visible = true;
			tint = GetVisionTint(cell.X, cell.Y, cell.Z);
		}

		return new FacilityRenderPlacement(
			inView && visible,
			sortKey,
			ResolveFacilityFootprintScreenCenter(footprint),
			tint);
	}

	private static Vector2 ResolveFacilityFootprintScreenCenter(IReadOnlyList<ZoneCell> footprint)
	{
		if (footprint.Count == 0)
			return Vector2.Zero;

		var minX = float.MaxValue;
		var minY = float.MaxValue;
		var maxX = float.MinValue;
		var maxY = float.MinValue;
		for (var index = 0; index < footprint.Count; index++)
		{
			var cell = footprint[index];
			var screen = IsoCoordUtil.WorldToScreen(cell.X, cell.Y, cell.Z);
			minX = Math.Min(minX, screen.X);
			minY = Math.Min(minY, screen.Y);
			maxX = Math.Max(maxX, screen.X);
			maxY = Math.Max(maxY, screen.Y);
		}

		return new Vector2((minX + maxX) * 0.5f, (minY + maxY) * 0.5f);
	}

	private static Vector2 ResolveFacilitySpritePosition(Vector2 pivot, Vector2 size, FacilitySpriteVisual visual)
	{
		return ResolveFacilitySpritePosition(
			pivot,
			size,
			visual.Scale,
			visual.Offset,
			visual.FrameBounds.Bottom);
	}

	private static Vector2 ResolveFacilitySpritePosition(
		Vector2 pivot,
		Vector2 size,
		Vector2 scale,
		Vector2 offset,
		int opaqueBottom)
	{
		var bottom = opaqueBottom > 0
			? opaqueBottom * scale.Y
			: size.Y * scale.Y;
		return pivot + FacilitySpriteBaseOffset + offset + new Vector2(
			-(size.X * scale.X) / 2f,
			-bottom);
	}

	private FacilityFrameBounds ResolveFacilityFrameBounds(string texturePath, Texture2D texture, Rect2? region)
	{
		var frameRect = region is { } resolvedRegion
			? new Rect2I(
				(int)Math.Round(resolvedRegion.Position.X),
				(int)Math.Round(resolvedRegion.Position.Y),
				(int)Math.Round(resolvedRegion.Size.X),
				(int)Math.Round(resolvedRegion.Size.Y))
			: new Rect2I(0, 0, (int)texture.GetWidth(), (int)texture.GetHeight());
		var cacheKey = $"{texturePath}|{frameRect.Position.X}|{frameRect.Position.Y}|{frameRect.Size.X}|{frameRect.Size.Y}";
		if (_facilityFrameBoundsCache.TryGetValue(cacheKey, out var cached))
			return cached;

		var sourceImage = ExtractImage(texture);
		if (sourceImage == null)
			return CacheFacilityFrameBounds(cacheKey, new FacilityFrameBounds(frameRect.Size.X, frameRect.Size.Y));

		var frameImage = sourceImage.GetRegion(frameRect);
		var usedRect = frameImage.GetUsedRect();
		if (usedRect.Size.X <= 0 || usedRect.Size.Y <= 0)
			return CacheFacilityFrameBounds(cacheKey, new FacilityFrameBounds(frameRect.Size.X, frameRect.Size.Y));

		return CacheFacilityFrameBounds(
			cacheKey,
			new FacilityFrameBounds(frameRect.Size.X, usedRect.End.Y));
	}

	private FacilityFrameBounds CacheFacilityFrameBounds(string cacheKey, FacilityFrameBounds bounds)
	{
		_facilityFrameBoundsCache[cacheKey] = bounds;
		return bounds;
	}

	private bool TryDrawWorldEntitySprite(Vector2 pos, string entityId, Color tint)
	{
		if (!TryResolveWorldEntitySpriteVisual(entityId, out var visual))
			return false;

		var size = visual.Region?.Size ?? visual.Texture.GetSize();
		var sprite = AcquireSprite();
		sprite.Centered = false;
		sprite.Texture = visual.Texture;
		sprite.TextureFilter = CanvasItem.TextureFilterEnum.Nearest;
		sprite.RegionEnabled = visual.Region != null;
		if (visual.Region is { } region)
			sprite.RegionRect = region;
		sprite.Scale = visual.Scale;
		sprite.Skew = 0f;
		sprite.ZIndex = 1;
		sprite.Modulate = tint;
		sprite.Position = pos + WorldEntitySpriteBaseOffset + visual.Offset + new Vector2(
			-(size.X * visual.Scale.X) / 2f,
			-(size.Y * visual.Scale.Y));
		sprite.Visible = true;
		return true;
	}

	private bool TryResolveWorldEntitySpriteVisual(string entityId, out WorldEntitySpriteVisual visual)
	{
		visual = default;
		var entry = ResAccess.GetEntry(entityId);
		if (entry == null || !IsTextureEntry(entry) || entry.TexturePath is not { Length: > 0 } texturePath)
			return false;

		var texture = ResAccess.Get<Texture2D>(texturePath);
		if (texture == null)
			return false;

		visual = new WorldEntitySpriteVisual(
			texture,
			ResolveWorldEntitySpriteRegion(entry, texture),
			ResolveWorldEntitySpriteScale(entry.Scale),
			ResolveEntitySpriteOffset(entry.Offset));
		return true;
	}

	private static Vector2 ResolveEntitySpriteScale(float[]? scale)
	{
		if (scale is [var x, var y] && x > 0f && y > 0f)
			return new Vector2(x, y);
		return DefaultEntitySpriteScale;
	}

	private static Vector2 ResolveFacilitySpriteScale(float[]? scale)
	{
		if (scale is [var x, var y] && x > 0f && y > 0f)
			return new Vector2(x, y);
		return DefaultFacilitySpriteScale;
	}

	private static Vector2 ResolveWorldEntitySpriteScale(float[]? scale)
	{
		if (scale is [var x, var y] && x > 0f && y > 0f)
			return new Vector2(x, y);
		return DefaultWorldEntitySpriteScale;
	}

	private static Vector2 ResolveEntitySpriteOffset(float[]? offset)
	{
		if (offset is [var x, var y])
			return new Vector2(x, y);
		return Vector2.Zero;
	}

	private static Rect2? ResolveEntitySpriteRegion(ResAccess.RenderEntry entry, Actor actor, Texture2D texture)
	{
		if (!entry.UseFacing)
			return null;

		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0 ? Math.Min(entry.FrameWidth, textureWidth) : textureWidth;
		var inferredFrameHeight = textureHeight % 8 == 0 ? textureHeight / 8 : textureHeight;
		var frameHeight = entry.FrameHeight > 0 ? Math.Min(entry.FrameHeight, textureHeight) : inferredFrameHeight;
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(
			DirectionalSpriteHelper.ResolveDirectionRow(actor.FacingX, actor.FacingY),
			0,
			rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private static Rect2? ResolveFacilitySpriteRegion(ResAccess.RenderEntry entry, FacilityInstance facility, Texture2D texture)
	{
		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0 ? Math.Min(entry.FrameWidth, textureWidth) : textureWidth;
		var frameHeight = entry.FrameHeight > 0 ? Math.Min(entry.FrameHeight, textureHeight) : textureHeight;
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(ResolveFacilityRotationRow(facility.Rotation), 0, rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private static Rect2? ResolveWorldEntitySpriteRegion(ResAccess.RenderEntry entry, Texture2D texture)
	{
		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		if (entry.FrameWidth <= 0 || entry.FrameHeight <= 0)
			return null;

		var frameWidth = Math.Min(entry.FrameWidth, textureWidth);
		var frameHeight = Math.Min(entry.FrameHeight, textureHeight);
		if (frameWidth == textureWidth && frameHeight == textureHeight)
			return null;

		return new Rect2(0, 0, frameWidth, frameHeight);
	}

	private ResAccess.RenderEntry? ResolveActorRenderEntry(Actor actor)
	{
		if (actor.Id == _state.PlayerId)
		{
			var appearance = PlayerAppearanceCatalog.GetOrDefault(_state.PlayerAppearanceId);
			var tuning = ResAccess.GetEntry("player");
			return new ResAccess.RenderEntry
			{
				Type = "sprite_sheet",
				SheetDir = appearance.SheetDir,
				DefaultAnim = appearance.DefaultAnim,
				Scale = tuning?.Scale,
				Offset = tuning?.Offset,
				FrameWidth = tuning?.FrameWidth ?? 0,
				FrameHeight = tuning?.FrameHeight ?? 0,
				UseFacing = true,
			};
		}

		if (TryGetSupportedActorEntry(actor.Id, out var direct))
			return direct;
		if (!string.IsNullOrWhiteSpace(actor.TemplateId) && TryGetSupportedActorEntry(actor.TemplateId, out var template))
			return template;
		if (actor.Race?.Id is { Length: > 0 } raceId && TryGetSupportedActorEntry(raceId, out var race))
			return race;

		return null;
	}

	private static ResAccess.RenderEntry? ResolveFacilityRenderEntry(FacilityInstance facility)
	{
		var entry = ResAccess.GetEntry($"facility_{facility.FacilityDefId}");
		return IsTextureEntry(entry) ? entry : null;
	}

	private static bool TryGetSupportedActorEntry(string key, out ResAccess.RenderEntry? entry)
	{
		entry = ResAccess.GetEntry(key);
		return IsTextureEntry(entry) || IsSpriteSheetEntry(entry);
	}

	private static bool IsSpriteSheetEntry(ResAccess.RenderEntry? entry) =>
		entry != null
		&& string.Equals(entry.Type, "sprite_sheet", StringComparison.OrdinalIgnoreCase)
		&& !string.IsNullOrWhiteSpace(entry.SheetDir);

	private static string ResolveCharacterSheetPath(ResAccess.RenderEntry entry)
	{
		if (string.IsNullOrWhiteSpace(entry.SheetDir))
			return string.Empty;
		var animationKey = string.IsNullOrWhiteSpace(entry.DefaultAnim) ? "Idle" : entry.DefaultAnim!;
		var sheetKey = CharacterSheetMap.TryGetValue(animationKey, out var resolved) ? resolved : "Idle";
		return $"{entry.SheetDir!.TrimEnd('/')}/{sheetKey}.png";
	}

	private static Rect2? ResolveCharacterSheetRegion(ResAccess.RenderEntry entry, Actor actor, Texture2D texture)
	{
		var textureWidth = (int)texture.GetWidth();
		var textureHeight = (int)texture.GetHeight();
		if (textureWidth <= 0 || textureHeight <= 0)
			return null;

		var frameWidth = entry.FrameWidth > 0
			? Math.Min(entry.FrameWidth, textureWidth)
			: Math.Min(DefaultCharacterSheetFrameWidth, textureWidth);
		var frameHeight = entry.FrameHeight > 0
			? Math.Min(entry.FrameHeight, textureHeight)
			: Math.Min(DefaultCharacterSheetFrameHeight, textureHeight);
		if (frameWidth <= 0 || frameHeight <= 0)
			return null;

		var rowCount = Math.Max(1, textureHeight / frameHeight);
		var row = Math.Clamp(
			DirectionalSpriteHelper.ResolveDirectionRow(actor.FacingX, actor.FacingY),
			0,
			rowCount - 1);
		return new Rect2(0, row * frameHeight, frameWidth, frameHeight);
	}

	private static bool IsTextureEntry(ResAccess.RenderEntry? entry) =>
		entry != null
		&& string.Equals(entry.Type, "texture", StringComparison.OrdinalIgnoreCase)
		&& !string.IsNullOrWhiteSpace(entry.TexturePath);

	private static int ResolveFacilityRotationRow(FacilityRotation rotation) => rotation switch
	{
		FacilityRotation.East => 1,
		FacilityRotation.South => 2,
		FacilityRotation.West => 3,
		_ => 0,
	};

	private static Color ResolveFacilityStageTint(FacilityStage stage) => stage switch
	{
		FacilityStage.Blueprint => new Color(0.62f, 0.78f, 1.0f, 0.82f),
		FacilityStage.DeliverMaterials => new Color(0.92f, 0.86f, 0.72f, 0.94f),
		FacilityStage.Construct => new Color(0.88f, 0.80f, 0.66f, 0.97f),
		FacilityStage.Broken => new Color(0.74f, 0.70f, 0.72f, 0.94f),
		_ => Colors.White,
	};

	private void DrawEntityMarker(Vector2 pos, string label, Color tint)
	{
		var s = AcquireSprite();
		s.Centered = true;
		s.RegionEnabled = false;
		s.Scale = Vector2.One;
		s.Texture = GetEntityMarkerTexture(label);
		s.Position = pos - new Vector2(0, IsoCoordUtil.TileHalfH * 0.5f);
		s.Skew = 0f;
		s.ZIndex = 1;
		s.Modulate = tint;
		s.Visible = true;
	}

	private ImageTexture GetEntityMarkerTexture(string label)
	{
		if (_entityMarkerCache.TryGetValue(label, out var cached)) return cached;

		if (label is HoverSideLeftFillTextureKey or HoverSideRightFillTextureKey)
		{
			var sideTex = BuildHoverSideFillTexture(isRight: label == HoverSideRightFillTextureKey);
			_entityMarkerCache[label] = sideTex;
			return sideTex;
		}

		if (label == HoverEdgeSegmentTextureKey)
		{
			var edgeTex = BuildHoverEdgeTexture();
			_entityMarkerCache[label] = edgeTex;
			return edgeTex;
		}

		const int size = 64;
		var image = Image.CreateEmpty(size, size, false, Image.Format.Rgba8);
		var center = (size - 1) * 0.5f;
		var radius = size * 0.5f - 4f;
		var color = label switch
		{
			"P" => new Color(0.2f, 0.6f, 1.0f),
			"!" => new Color(1.0f, 0.2f, 0.2f),
			"?" => new Color(0.2f, 0.8f, 0.2f),
			_ => Colors.White,
		};
		for (var py = 0; py < size; py++)
		for (var px = 0; px < size; px++)
		{
			if (label is "hover_diamond_fill" or "hover_diamond_outline")
			{
				var nx = Math.Abs(px - center) / (size * 0.5f);
				var ny = Math.Abs(py - center) / (size * 0.5f);
				var d = nx + ny;
				if (d > 1f)
				{
					image.SetPixel(px, py, Colors.Transparent);
					continue;
				}

				if (label == "hover_diamond_outline")
				{
					var edgeAlpha = Math.Clamp((d - 0.85f) / 0.15f, 0f, 1f);
					var innerFade = 1f - Math.Clamp((d - 0.15f) / 0.45f, 0f, 1f);
					var alpha = Math.Max(edgeAlpha, innerFade * 0.06f);
					image.SetPixel(px, py, new Color(color.R, color.G, color.B, alpha));
				}
				else
				{
					var edgeSoft = 1f - Math.Clamp((d - 0.80f) / 0.20f, 0f, 1f);
					var centerGlow = 1f - Math.Clamp(d / 0.72f, 0f, 1f);
					var alpha = Math.Clamp(0.22f + centerGlow * 0.62f + edgeSoft * 0.22f, 0f, 1f);
					image.SetPixel(px, py, new Color(color.R, color.G, color.B, alpha));
				}
				continue;
			}

			var dx = px - center;
			var dy = py - center;
			image.SetPixel(px, py, dx * dx + dy * dy <= radius * radius ? color : Colors.Transparent);
		}
		var tex = ImageTexture.CreateFromImage(image);
		_entityMarkerCache[label] = tex;
		return tex;
	}

	private static ImageTexture BuildHoverSideFillTexture(bool isRight)
	{
		var image = Image.CreateEmpty(SideTextureWidth, SideTextureHeight, false, Image.Format.Rgba8);
		for (var px = 0; px < SideTextureWidth; px++)
		{
			var pyStart = isRight
				? (int)Math.Round((SideTextureWidth - 1 - px) * IsoCoordUtil.TileHalfH / (double)(SideTextureWidth - 1))
				: (int)Math.Round(px * IsoCoordUtil.TileHalfH / (double)(SideTextureWidth - 1));
			var outerEdgeFactor = isRight
				? px / (float)(SideTextureWidth - 1)
				: 1f - px / (float)(SideTextureWidth - 1);

			for (var dy = 0; dy < SideFaceHeight; dy++)
			{
				var py = pyStart + dy;
				if (py >= SideTextureHeight)
					break;

				var depthFactor = 1f - dy / (float)Math.Max(1, SideFaceHeight - 1);
				var alpha = Math.Clamp(0.18f + depthFactor * 0.30f + outerEdgeFactor * 0.10f, 0f, 1f);
				image.SetPixel(px, py, new Color(1f, 1f, 1f, alpha));
			}
		}

		return ImageTexture.CreateFromImage(image);
	}

	private static ImageTexture BuildHoverEdgeTexture()
	{
		const int width = 32;
		const int height = 4;
		var image = Image.CreateEmpty(width, height, false, Image.Format.Rgba8);
		var centerX = (width - 1) * 0.5f;
		var centerY = (height - 1) * 0.5f;

		for (var py = 0; py < height; py++)
		for (var px = 0; px < width; px++)
		{
			var nx = Math.Abs(px - centerX) / (width * 0.5f);
			var ny = Math.Abs(py - centerY) / (height * 0.5f);
			var alpha = Math.Clamp((1f - ny * ny) * (0.78f + (1f - nx * nx) * 0.22f), 0f, 1f);
			image.SetPixel(px, py, new Color(1f, 1f, 1f, alpha));
		}

		return ImageTexture.CreateFromImage(image);
	}

	private static HoverVolumeGeometry BuildHoverVolumeGeometry(Vector2 topCenter)
	{
		var verticalOffset = new Vector2(0f, IsoCoordUtil.ZStep);
		var top = topCenter + new Vector2(0f, -IsoCoordUtil.TileHalfH);
		var right = topCenter + new Vector2(IsoCoordUtil.TileHalfW, 0f);
		var bottom = topCenter + new Vector2(0f, IsoCoordUtil.TileHalfH);
		var left = topCenter + new Vector2(-IsoCoordUtil.TileHalfW, 0f);
		return new HoverVolumeGeometry(
			topCenter,
			top,
			right,
			bottom,
			left,
			right + verticalOffset,
			bottom + verticalOffset,
			left + verticalOffset);
	}

	private static string[] GetHoverTextureKeys() =>
	[
		HoverDiamondOutlineTextureKey,
		HoverDiamondFillTextureKey,
		HoverSideLeftFillTextureKey,
		HoverSideRightFillTextureKey,
		HoverEdgeSegmentTextureKey,
	];

	// ── Sprite Pool ──

	private void BeginFrame()
	{
		_spriteCount = 0;
		_faceBatchCanvas?.SetCommands(Array.Empty<FaceSpriteCommand>());
	}

	private void EndFrame()
	{
		for (var i = _spriteCount; i < _spritePool.Count; i++)
			_spritePool[i].Visible = false;
	}

	private Sprite2D AcquireSprite()
	{
		var idx = _spriteCount++;
		if (idx < _spritePool.Count) return _spritePool[idx];
		var sprite = new Sprite2D
		{
			Name = "VoxelSprite" + _spritePool.Count.ToString(),
			Centered = true,
			TextureFilter = CanvasItem.TextureFilterEnum.Nearest,
		};
		_root!.AddChild(sprite);
		_spritePool.Add(sprite);
		return sprite;
	}

	private void UpdateCamera(int cx, int cy, int cz)
	{
		if (_camera == null) return;
		var target = IsoCoordUtil.WorldToScreen(cx, cy, cz);
		if (_editorViewActive)
			_editorCameraTarget = target;
		else
			_camera.Position = target;
	}

	public void SetEditorCameraScreenTarget(Vector2 target)
	{
		_editorCameraTarget = target;
	}

	public void ClearEditorCameraSmoothing()
	{
		_editorCameraTarget = null;
	}

